using ASMILE.BO.Core.FrontOffice.Foundation.Identifiers;

namespace ASMILE.BO.Core.FrontOffice.HotelMasterData;

public enum HotelFolioTypeKind { Guest = 1, Company = 2, Master = 3, Group = 4, CityLedger = 5 }

public sealed class HotelFolioProfile
{
    private HotelFolioProfile() { }
    public Guid HotelFolioProfileId { get; private set; } public Guid PropertyId { get; private set; } public string Code { get; private set; } = string.Empty; public string Name { get; private set; } = string.Empty; public HotelFolioTypeKind Kind { get; private set; } public bool AutoCreate { get; private set; } public bool AutoRouting { get; private set; } public bool AllowSplit { get; private set; } public bool AllowMerge { get; private set; } public bool AllowTransfer { get; private set; } public string? ChargeRouting { get; private set; } public string? PaymentRouting { get; private set; } public DateTime EffectiveFrom { get; private set; } public DateTime EffectiveTo { get; private set; } public string? Description { get; private set; } public bool IsActive { get; private set; } public DateTime CreatedAtUtc { get; private set; } public Guid? CreatedBy { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid? UpdatedBy { get; private set; } public byte[]? RowVersion { get; private set; }
    public static HotelFolioProfile Create(PropertyId propertyId, string code, string name, HotelFolioTypeKind kind, bool autoCreate, bool autoRouting, bool allowSplit, bool allowMerge, bool allowTransfer, string? chargeRouting, string? paymentRouting, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId)
    { Validate(code, name, kind, from, to); return new() { HotelFolioProfileId = Uuid7.NewGuid(), PropertyId = propertyId.Value, Code = code.Trim().ToUpperInvariant(), Name = name.Trim(), Kind = kind, AutoCreate = autoCreate, AutoRouting = autoRouting, AllowSplit = allowSplit, AllowMerge = allowMerge, AllowTransfer = allowTransfer, ChargeRouting = Normalize(chargeRouting), PaymentRouting = Normalize(paymentRouting), EffectiveFrom = from.Date, EffectiveTo = to.Date, Description = Normalize(description), IsActive = true, CreatedAtUtc = nowUtc, CreatedBy = actorId?.Value, UpdatedAtUtc = nowUtc, UpdatedBy = actorId?.Value }; }
    public void Update(string code, string name, HotelFolioTypeKind kind, bool autoCreate, bool autoRouting, bool allowSplit, bool allowMerge, bool allowTransfer, string? chargeRouting, string? paymentRouting, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId)
    { Validate(code, name, kind, from, to); Code = code.Trim().ToUpperInvariant(); Name = name.Trim(); Kind = kind; AutoCreate = autoCreate; AutoRouting = autoRouting; AllowSplit = allowSplit; AllowMerge = allowMerge; AllowTransfer = allowTransfer; ChargeRouting = Normalize(chargeRouting); PaymentRouting = Normalize(paymentRouting); EffectiveFrom = from.Date; EffectiveTo = to.Date; Description = Normalize(description); Touch(nowUtc, actorId); }
    public void Activate(DateTime nowUtc, ActorId? actorId) { IsActive = true; Touch(nowUtc, actorId); } public void Deactivate(DateTime nowUtc, ActorId? actorId) { IsActive = false; Touch(nowUtc, actorId); }
    private void Touch(DateTime nowUtc, ActorId? actorId) { UpdatedAtUtc = nowUtc; UpdatedBy = actorId?.Value; } private static void Validate(string code, string name, HotelFolioTypeKind kind, DateTime from, DateTime to) { if (string.IsNullOrWhiteSpace(code)) throw new ArgumentException("HOTEL_FOLIO_CODE_REQUIRED"); if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("HOTEL_FOLIO_NAME_REQUIRED"); if (!Enum.IsDefined(kind)) throw new ArgumentException("HOTEL_FOLIO_TYPE_INVALID"); if (to.Date < from.Date) throw new ArgumentException("HOTEL_FOLIO_EFFECTIVE_RANGE_INVALID"); } private static string? Normalize(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}
